#include <iostream>
#include <vector>
#include <queue>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
using std::vector;
using std::priority_queue;
using std::greater;


typedef long long ll;

ll solve (const ll n, const vector<ll> &a) {
	ll ans = 0;

	priority_queue<ll, vector<ll> > que;
	for (ll i = 0; i < n; i++) {
		if (i == 0) {
			que.push(a[i*2-0]);
		} else {
			que.push(a[i*2-1]);
			que.push(a[i*2-0]);
		}

		ll v = que.top();
		que.pop();

		ans += v;
	}

	return ans;
}

int main (void) {
	int T;
	cin >> T;
	while (T--) {
		ll n;
		cin >> n;
		vector<ll> a(n*2);
		for (ll i = 0; i < n*2; i++) {
			cin >> a[i];
		}

		cout << solve(n, a) << "\n";
	}

	return 0;
}

#include <bits/stdc++.h>
#include <atcoder/all>
using namespace std;

int op(int l, int r) { return min(l, r); }
int e() { return numeric_limits<int>::max(); }
int mapping(int l, int r) { return l + r; }
int composition(int l, int r) { return l + r; }
int id() { return 0; }

int main() {
	int t; cin >> t;
	while (t--) {
		int N; cin >> N;
		vector<pair<int, int>> A(2*N); //Aの値と元の位置のペア
		for (int i=0; i<2*N; ++i) {
			cin >> A[i].first;
			A[i].second = i;
		}
		ranges::sort(A, greater<>()); //Aを値の降順にソート

		vector<int> B_init(2*N);
		for (int i=0; i<2*N; ++i) B_init[i] = (2*N-i)/2; //Bの初期値を設定
		atcoder::lazy_segtree<int, op, e, int, mapping, composition, id> B(B_init); //区間加算,区間min取得の遅延セグメント木

		long long ans = 0;
		for (int i=0; i<2*N; ++i) {
			if (B.prod(0, A[i].second+1) <= 0) continue;
			ans += A[i].first;
			B.apply(0, A[i].second+1, -1); //Bの更新
		}
		cout << ans << "\n";
	}
}
